const dictionaries = Object.fromEntries(SUPPORTED_LOCALES.map(({ id }) => [id, {}]));
function addRows(source) {
  for (const line of source.trim().split('\n')) {
    const [key, ...values] = line.split('|');
    if (values.length !== SUPPORTED_LOCALES.length || values.some(value => !value.trim())) {
      throw new Error(`Incomplete translations for ${key}`);
    }
    SUPPORTED_LOCALES.forEach(({ id }, index) => {
      if (Object.hasOwn(dictionaries[id], key)) throw new Error(`Duplicate translation key: ${key}`);
      dictionaries[id][key] = values[index];
    });
  }
}
addRows(rows);

