const aliases = {
  'module.cs-admin.users': 'module.workflow.users',
  'module.cs-admin.roles': 'module.workflow.roles',
  'field.name': 'ui.name', 'field.title': 'ui.title', 'field.description': 'ui.description',
  'field.language': 'ui.language', 'field.device': 'ui.device', 'field.status': 'ui.status',
  'field.reason': 'ui.reason', 'field.history': 'ui.history', 'field.result': 'ui.result',
  'field.records': 'ui.records', 'field.scenario': 'ui.scenario', 'field.actions': 'ui.actions',
  'field.item': 'ui.item', 'field.version': 'ui.revision', 'field.packageVersion': 'ui.revision',
  'field.error': 'ui.failure', 'field.draft': 'value.draft', 'field.remark': 'ui.note',
  'action.create': 'ui.create', 'action.edit': 'ui.edit', 'action.delete': 'ui.delete',
  'action.view': 'ui.details', 'action.refresh': 'ui.refresh', 'action.reply': 'ui.reply',
  'action.history': 'ui.history', 'action.close': 'ui.close', 'action.publish': 'ui.publish',
  'action.preview': 'ui.preview', 'action.upload': 'ui.upload', 'action.download': 'ui.download',
  'action.send': 'ui.send', 'action.submit': 'ui.submit', 'action.test': 'ui.test',
  'action.reset': 'ui.resetData',
  'action.comment': 'field.comment', 'action.complete': 'ui.resolve', 'action.pin': 'field.pinned',
  'error.FORBIDDEN': 'ui.permissionDenied', 'error.VERSION_CONFLICT': 'ui.versionConflict',
  'error.NOT_FOUND': 'ui.notFound', 'error.VALIDATION': 'ui.validationError',
  'value.all': 'ui.all', 'value.desktop': 'ui.desktop', 'value.mobile': 'ui.mobile',
  'value.consumer': 'role.consumer', 'value.agent': 'role.agent', 'value.supervisor': 'role.supervisor',
  'value.processor': 'role.processor', 'value.team-admin': 'role.team-admin', 'value.admin': 'role.admin'
};
for (const { id: localeId } of SUPPORTED_LOCALES) {
  const dictionary = dictionaries[localeId];
  for (const [key, source] of Object.entries(aliases)) {
    if (!Object.hasOwn(dictionary, source)) throw new Error(`Invalid translation alias: ${source}`);
    dictionary[key] = dictionary[source];
  }
  for (const locale of SUPPORTED_LOCALES) dictionary[`value.${locale.id}`] = locale.label;
  for (const operation of ['create', 'edit', 'delete']) {
    for (const entity of ['category', 'group', 'suspendRule', 'tag', 'task']) {
      const suffix = entity[0].toUpperCase() + entity.slice(1);
      dictionary[`action.${operation}${suffix}`] = dictionary[`phrase.${operation}`].replace('{name}', dictionary[`entity.${entity}`]);
    }
  }
  const relations = {
    applicationId: 'application', creatorId: 'creator', assigneeId: 'assignee', assigneeIds: 'assignee',
    actorId: 'actor', agentId: 'staff', templateId: 'template', templateIds: 'template', teamId: 'team', teamIds: 'team',
    userId: 'user', userIds: 'user', adminIds: 'user', organizationId: 'organization',
    feedbackId: 'feedback', feedbackIds: 'feedback', consumerId: 'consumer', gameId: 'game', gameIds: 'game',
    typeId: 'type', typeIds: 'type', feedbackTypeIds: 'type', workflowTicketId: 'workflowTicket',
    nodeId: 'node', projectId: 'project', fileId: 'file', fileIds: 'file', groupId: 'group', categoryId: 'category',
    sessionId: 'session', staffId: 'staff', staffIds: 'staff', staffGroupId: 'staffGroup',
    cardTemplateId: 'cardTemplate', evaluationId: 'evaluation', messageId: 'message', tagIds: 'tag',
    packageIds: 'package', taskId: 'task', storageId: 'storage', welcomeMessageId: 'welcomeMessage',
    parentId: 'parent', nextAssigneeId: 'nextAssignee', relatedFeedbackId: 'relatedFeedback',
    sourceId: 'source', knowledgeCategoryId: 'knowledgeCategory', workflowTemplateId: 'workflowTemplate',
    workflowTemplateIds: 'workflowTemplate', senderId: 'sender', mentionIds: 'mention'
  };
  for (const [key, entity] of Object.entries(relations)) {
    const template = dictionary[key.endsWith('Ids') ? 'phrase.identifiers' : 'phrase.identifier'];
    dictionary[`field.${key}`] = template.replace('{name}', dictionary[`entity.${entity}`]);
  }
  dictionary['field.id'] = 'ID';
  dictionary['field.dify'] = 'Dify';
  dictionary['field.mime'] = 'MIME';
  Object.assign(dictionary, { 'value.ai': 'AI', 'value.api': 'API', 'value.vip': 'VIP', 'value.GT': '>', 'value.GE': '≥' });
  dictionary['value.success'] = dictionary['ui.success'];
  dictionary['value.failure'] = dictionary['ui.failure'];
  for (const key of ['enabled', 'invited', 'ready', 'success', 'failure', 'ended', 'approved', 'online', 'offline', 'busy']) {
    dictionary[`status.${key}`] = dictionary[`value.${key}`];
  }
}

export const messages = Object.freeze(Object.fromEntries(Object.entries(dictionaries).map(([id, values]) => [id, Object.freeze(values)])));

export function translate(locale, key, vars = {}) {
  if (!Object.hasOwn(messages, locale)) throw new RangeError(`Unsupported locale: ${locale}`);
  if (!Object.hasOwn(messages[locale], key)) throw new RangeError(`Missing translation key: ${key} (${locale})`);
  return messages[locale][key].replace(/\{([A-Za-z][A-Za-z0-9]*)\}/g, (_, name) => {
    if (!Object.hasOwn(vars, name)) throw new TypeError(`Missing translation variable: ${name}`);
    return String(vars[name]);
  });
}
